from copy import deepcopy


def apply_form_actions(initial, actions):
    if not isinstance(initial, dict) or any(not isinstance(k, str) for k in initial):
        raise ValueError("invalid initial form")
    if not isinstance(actions, list):
        raise ValueError("actions must be a list")
    state = deepcopy(initial)
    expected = {
        "set": {"op", "field", "value"},
        "copy": {"op", "source", "target"},
        "remove": {"op", "field"},
        "require": {"op", "field"},
    }
    for raw in actions:
        if not isinstance(raw, dict) or raw.get("op") not in expected:
            raise ValueError("unknown action")
        action = deepcopy(raw)
        op = action["op"]
        if set(action) != expected[op]:
            raise ValueError("invalid action fields")
        names = [action[k] for k in ("field", "source", "target") if k in action]
        if any(not isinstance(name, str) or not name for name in names):
            raise ValueError("invalid field name")
        if op == "set":
            state[action["field"]] = deepcopy(action["value"])
        elif op == "copy":
            source, target = action["source"], action["target"]
            if source == target or source not in state:
                raise ValueError("invalid copy")
            state[target] = state[source]
        elif op == "remove":
            if action["field"] not in state:
                raise ValueError("missing field")
            del state[action["field"]]
        elif action["field"] not in state or state[action["field"]] is None or state[action["field"]] == "":
            raise ValueError("required field is empty")
    return deepcopy(state)

